 	httpc    *http.Client
 	tokenURL string // core auth /oauth/token, e.g. https://us.auth.example.com/oauth/token
 	audience string // jurisdiction host bare origin, e.g. https://us.example.com
 	clientID string // public OAuth client, e.g. entire-cli
